select case when c.age >= 58 then 'high' when c.age >= 27 then 'mid' else 'low' end as age_bucket, year(c.signup_date) as signup_year, sum(case when a.status = 'FROZEN' then a.balance else 0 end) as frozen_balance, sum(case when a.account_type = 'SAVINGS' then a.balance else 0 end) as savings_balance from accounts a inner join customers c on c.id = a.customer_id group by case when c.age >= 58 then 'high' when c.age >= 27 then 'mid' else 'low' end, year(c.signup_date) order by 4 asc, 2 desc;
